// Function BmScript.RBMBehaviour_GangMovementBase.GetBreakVars
// [0x00420002] (FUNC_Defined | FUNC_Public | FUNC_HasOutParms | FUNC_AllFlags)
// Parameter Info:
// struct FVector                 HitLoc                         (CPF_Parm | CPF_OutParm)
// struct FVector                 HitNorm                        (CPF_Parm | CPF_OutParm)
// struct FVector                 HitSpeed                       (CPF_Parm | CPF_OutParm)
// class AActor*                  ThrownActor                    (CPF_Parm | CPF_OutParm)

void URBMBehaviour_GangMovementBase::GetBreakVars(struct FVector& outHitLoc, struct FVector& outHitNorm, struct FVector& outHitSpeed, class AActor*& outThrownActor)
{
	static UFunction* uFnGetBreakVars = nullptr;

	if (!uFnGetBreakVars)
	{
		uFnGetBreakVars = UFunction::FindFunction("Function BmScript.RBMBehaviour_GangMovementBase.GetBreakVars");
	}

	URBMBehaviour_GangMovementBase_execGetBreakVars_Params GetBreakVars_Params;
	memset(&GetBreakVars_Params, 0, sizeof(GetBreakVars_Params));
	if (!uFnGetBreakVars)
	{
		return;
	}

	memcpy_s(&GetBreakVars_Params.HitLoc, sizeof(GetBreakVars_Params.HitLoc), &outHitLoc, sizeof(outHitLoc));
	memcpy_s(&GetBreakVars_Params.HitNorm, sizeof(GetBreakVars_Params.HitNorm), &outHitNorm, sizeof(outHitNorm));
	memcpy_s(&GetBreakVars_Params.HitSpeed, sizeof(GetBreakVars_Params.HitSpeed), &outHitSpeed, sizeof(outHitSpeed));
	GetBreakVars_Params.ThrownActor = outThrownActor;

	this->ProcessEvent(uFnGetBreakVars, &GetBreakVars_Params, nullptr);

	memcpy_s(&outHitLoc, sizeof(outHitLoc), &GetBreakVars_Params.HitLoc, sizeof(GetBreakVars_Params.HitLoc));
	memcpy_s(&outHitNorm, sizeof(outHitNorm), &GetBreakVars_Params.HitNorm, sizeof(GetBreakVars_Params.HitNorm));
	memcpy_s(&outHitSpeed, sizeof(outHitSpeed), &GetBreakVars_Params.HitSpeed, sizeof(GetBreakVars_Params.HitSpeed));
	outThrownActor = GetBreakVars_Params.ThrownActor;
}

