// class TArray<class UObject*>   outObjects                     (CPF_Parm | CPF_OutParm | CPF_NeedCtorLink)

bool URBMBehaviour_BagCarrier::GetJoiningLocations(class TArray<struct FVector>& outOutLocations, class TArray<class UObject*>& outOutObjects)
{
	static UFunction* uFnGetJoiningLocations = nullptr;

	if (!uFnGetJoiningLocations)
	{
		uFnGetJoiningLocations = UFunction::FindFunction("Function BmScript.RBMBehaviour_BagCarrier.GetJoiningLocations");
	}

	URBMBehaviour_BagCarrier_execGetJoiningLocations_Params GetJoiningLocations_Params;
	memset(&GetJoiningLocations_Params, 0, sizeof(GetJoiningLocations_Params));
	if (!uFnGetJoiningLocations)
	{
		return {};
	}

	memcpy_s(&GetJoiningLocations_Params.outLocations, sizeof(GetJoiningLocations_Params.outLocations), &outOutLocations, sizeof(outOutLocations));
	memcpy_s(&GetJoiningLocations_Params.outObjects, sizeof(GetJoiningLocations_Params.outObjects), &outOutObjects, sizeof(outOutObjects));

	this->ProcessEvent(uFnGetJoiningLocations, &GetJoiningLocations_Params, nullptr);

	memcpy_s(&outOutLocations, sizeof(outOutLocations), &GetJoiningLocations_Params.outLocations, sizeof(GetJoiningLocations_Params.outLocations));
	memcpy_s(&outOutObjects, sizeof(outOutObjects), &GetJoiningLocations_Params.outObjects, sizeof(GetJoiningLocations_Params.outObjects));

	return GetJoiningLocations_Params.ReturnValue;
}

