// Function BmScript.RBMBehaviour_CityJogAway.OverrideGetupStances
// [0x00420002] (FUNC_Defined | FUNC_Public | FUNC_HasOutParms | FUNC_AllFlags)
// Parameter Info:
// bool                           ReturnValue                    (CPF_Parm | CPF_OutParm | CPF_ReturnParm)
// class FName                    MovementStance                 (CPF_Parm | CPF_OutParm)
// class FName                    WeaponStance                   (CPF_Parm | CPF_OutParm)

bool URBMBehaviour_CityJogAway::OverrideGetupStances(class FName& outMovementStance, class FName& outWeaponStance)
{
	static UFunction* uFnOverrideGetupStances = nullptr;

	if (!uFnOverrideGetupStances)
	{
		uFnOverrideGetupStances = UFunction::FindFunction("Function BmScript.RBMBehaviour_CityJogAway.OverrideGetupStances");
	}

	URBMBehaviour_CityJogAway_execOverrideGetupStances_Params OverrideGetupStances_Params;
	memset(&OverrideGetupStances_Params, 0, sizeof(OverrideGetupStances_Params));
	if (!uFnOverrideGetupStances)
	{
		return {};
	}

	memcpy_s(&OverrideGetupStances_Params.MovementStance, sizeof(OverrideGetupStances_Params.MovementStance), &outMovementStance, sizeof(outMovementStance));
	memcpy_s(&OverrideGetupStances_Params.WeaponStance, sizeof(OverrideGetupStances_Params.WeaponStance), &outWeaponStance, sizeof(outWeaponStance));

	this->ProcessEvent(uFnOverrideGetupStances, &OverrideGetupStances_Params, nullptr);

	memcpy_s(&outMovementStance, sizeof(outMovementStance), &OverrideGetupStances_Params.MovementStance, sizeof(OverrideGetupStances_Params.MovementStance));
	memcpy_s(&outWeaponStance, sizeof(outWeaponStance), &OverrideGetupStances_Params.WeaponStance, sizeof(OverrideGetupStances_Params.WeaponStance));

	return OverrideGetupStances_Params.ReturnValue;
}

