// class ARProjectile_GrenadeBase* NadeProj                       (CPF_OptionalParm | CPF_Parm | CPF_OutParm)

bool ARPawnVillainGunPredFull::DoGrenadeVentThrow(const struct FVector& ThrowVel, const struct FRotator& SpawnRot, const struct FVector& TargetLoc, class ARProjectile_GrenadeBase*& optionalOutNadeProj)
{
	static UFunction* uFnDoGrenadeVentThrow = nullptr;

	if (!uFnDoGrenadeVentThrow)
	{
		uFnDoGrenadeVentThrow = UFunction::FindFunction("Function BmScript.RPawnVillainGunPredFull.DoGrenadeVentThrow");
	}

	ARPawnVillainGunPredFull_execDoGrenadeVentThrow_Params DoGrenadeVentThrow_Params;
	memset(&DoGrenadeVentThrow_Params, 0, sizeof(DoGrenadeVentThrow_Params));
	if (!uFnDoGrenadeVentThrow)
	{
		return {};
	}

	memcpy_s(&DoGrenadeVentThrow_Params.ThrowVel, sizeof(DoGrenadeVentThrow_Params.ThrowVel), &ThrowVel, sizeof(ThrowVel));
	memcpy_s(&DoGrenadeVentThrow_Params.SpawnRot, sizeof(DoGrenadeVentThrow_Params.SpawnRot), &SpawnRot, sizeof(SpawnRot));
	memcpy_s(&DoGrenadeVentThrow_Params.TargetLoc, sizeof(DoGrenadeVentThrow_Params.TargetLoc), &TargetLoc, sizeof(TargetLoc));
	DoGrenadeVentThrow_Params.NadeProj = optionalOutNadeProj;

	this->ProcessEvent(uFnDoGrenadeVentThrow, &DoGrenadeVentThrow_Params, nullptr);

	optionalOutNadeProj = DoGrenadeVentThrow_Params.NadeProj;

	return DoGrenadeVentThrow_Params.ReturnValue;
}

