	if (!uFnGetActorThoughts)
	{
		return;
	}

	memcpy_s(&GetActorThoughts_Params.IndentString, sizeof(GetActorThoughts_Params.IndentString), &optionalIndentString, sizeof(optionalIndentString));
	memcpy_s(&GetActorThoughts_Params.ThoughtList, sizeof(GetActorThoughts_Params.ThoughtList), &outThoughtList, sizeof(outThoughtList));
	memcpy_s(&GetActorThoughts_Params.ThoughtLocationOverride, sizeof(GetActorThoughts_Params.ThoughtLocationOverride), &outThoughtLocationOverride, sizeof(outThoughtLocationOverride));

	this->ProcessEvent(uFnGetActorThoughts, &GetActorThoughts_Params, nullptr);

	memcpy_s(&outThoughtList, sizeof(outThoughtList), &GetActorThoughts_Params.ThoughtList, sizeof(GetActorThoughts_Params.ThoughtList));
	memcpy_s(&outThoughtLocationOverride, sizeof(outThoughtLocationOverride), &GetActorThoughts_Params.ThoughtLocationOverride, sizeof(GetActorThoughts_Params.ThoughtLocationOverride));
