// Function BmScript.RVehicleBatmobile.ChooseAlternateSpawnPoint
// [0x00C20002] (FUNC_Defined | FUNC_Public | FUNC_HasOutParms | FUNC_HasDefaults | FUNC_AllFlags)
// Parameter Info:
// int32_t                        ReturnValue                    (CPF_Parm | CPF_OutParm | CPF_ReturnParm)
// struct FVector                 pos                            (CPF_Parm | CPF_OutParm)
// struct FRotator                Rot                            (CPF_Parm | CPF_OutParm)

int32_t ARVehicleBatmobile::ChooseAlternateSpawnPoint(struct FVector& outPos, struct FRotator& outRot)
{
	static UFunction* uFnChooseAlternateSpawnPoint = nullptr;

	if (!uFnChooseAlternateSpawnPoint)
	{
		uFnChooseAlternateSpawnPoint = UFunction::FindFunction("Function BmScript.RVehicleBatmobile.ChooseAlternateSpawnPoint");
	}

	ARVehicleBatmobile_execChooseAlternateSpawnPoint_Params ChooseAlternateSpawnPoint_Params;
	memset(&ChooseAlternateSpawnPoint_Params, 0, sizeof(ChooseAlternateSpawnPoint_Params));
	if (!uFnChooseAlternateSpawnPoint)
	{
		return {};
	}

	memcpy_s(&ChooseAlternateSpawnPoint_Params.pos, sizeof(ChooseAlternateSpawnPoint_Params.pos), &outPos, sizeof(outPos));
	memcpy_s(&ChooseAlternateSpawnPoint_Params.Rot, sizeof(ChooseAlternateSpawnPoint_Params.Rot), &outRot, sizeof(outRot));

	this->ProcessEvent(uFnChooseAlternateSpawnPoint, &ChooseAlternateSpawnPoint_Params, nullptr);

	memcpy_s(&outPos, sizeof(outPos), &ChooseAlternateSpawnPoint_Params.pos, sizeof(ChooseAlternateSpawnPoint_Params.pos));
	memcpy_s(&outRot, sizeof(outRot), &ChooseAlternateSpawnPoint_Params.Rot, sizeof(ChooseAlternateSpawnPoint_Params.Rot));

	return ChooseAlternateSpawnPoint_Params.ReturnValue;
}

