	if (!uFnTakeDamageFromWeapon)
	{
		return {};
	}

	TakeDamageFromWeapon_Params.DamageAmount = DamageAmount;
	TakeDamageFromWeapon_Params.EventInstigator = EventInstigator;
	memcpy_s(&TakeDamageFromWeapon_Params.HitLocation, sizeof(TakeDamageFromWeapon_Params.HitLocation), &HitLocation, sizeof(HitLocation));
