	TakeDamageFromWeapon_Params.DamageType = DamageType;
	memcpy_s(&TakeDamageFromWeapon_Params.HitInfo, sizeof(TakeDamageFromWeapon_Params.HitInfo), &optionalHitInfo, sizeof(optionalHitInfo));
	TakeDamageFromWeapon_Params.DamageCauser = optionalDamageCauser;
	TakeDamageFromWeapon_Params.bHeadShot = optionalBHeadShot;

	this->ProcessEvent(uFnTakeDamageFromWeapon, &TakeDamageFromWeapon_Params, nullptr);

	return static_cast<EWeaponDamageResult>(TakeDamageFromWeapon_Params.ReturnValue);
