// class FName                    FailName                       (CPF_Parm | CPF_OutParm)
// class FName                    CounterName                    (CPF_Parm | CPF_OutParm)

void ARBMWeaponCombatExpertSword::GetMultiAttackAnimNames(class ARPawnPlayerCombat* Player, class FName& outIntroName, class FName& outAttackName, class FName& outFailName, class FName& outCounterName)
{
	static UFunction* uFnGetMultiAttackAnimNames = nullptr;

	if (!uFnGetMultiAttackAnimNames)
	{
		uFnGetMultiAttackAnimNames = UFunction::FindFunction("Function BmScript.RBMWeaponCombatExpertSword.GetMultiAttackAnimNames");
	}

	ARBMWeaponCombatExpertSword_execGetMultiAttackAnimNames_Params GetMultiAttackAnimNames_Params;
	memset(&GetMultiAttackAnimNames_Params, 0, sizeof(GetMultiAttackAnimNames_Params));
	if (!uFnGetMultiAttackAnimNames)
	{
		return;
	}

	GetMultiAttackAnimNames_Params.Player = Player;
	memcpy_s(&GetMultiAttackAnimNames_Params.IntroName, sizeof(GetMultiAttackAnimNames_Params.IntroName), &outIntroName, sizeof(outIntroName));
	memcpy_s(&GetMultiAttackAnimNames_Params.AttackName, sizeof(GetMultiAttackAnimNames_Params.AttackName), &outAttackName, sizeof(outAttackName));
	memcpy_s(&GetMultiAttackAnimNames_Params.FailName, sizeof(GetMultiAttackAnimNames_Params.FailName), &outFailName, sizeof(outFailName));
	memcpy_s(&GetMultiAttackAnimNames_Params.CounterName, sizeof(GetMultiAttackAnimNames_Params.CounterName), &outCounterName, sizeof(outCounterName));

	this->ProcessEvent(uFnGetMultiAttackAnimNames, &GetMultiAttackAnimNames_Params, nullptr);

	memcpy_s(&outIntroName, sizeof(outIntroName), &GetMultiAttackAnimNames_Params.IntroName, sizeof(GetMultiAttackAnimNames_Params.IntroName));
	memcpy_s(&outAttackName, sizeof(outAttackName), &GetMultiAttackAnimNames_Params.AttackName, sizeof(GetMultiAttackAnimNames_Params.AttackName));
	memcpy_s(&outFailName, sizeof(outFailName), &GetMultiAttackAnimNames_Params.FailName, sizeof(GetMultiAttackAnimNames_Params.FailName));
	memcpy_s(&outCounterName, sizeof(outCounterName), &GetMultiAttackAnimNames_Params.CounterName, sizeof(GetMultiAttackAnimNames_Params.CounterName));
}

